window.RP_SESSION={"id":"S-b16ae0671ee9","messages":[{"id":"RP-III-0039258","time":"2026-03-04T16:42:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"쾅! 오늘도 연병장은 시끄럽습니다···. 마리우스가 투구를 벗고 등장한지, 삼일 정도 되었을까요. 하루도 조용하지 않습니다.","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0039259","time":"2026-03-04T16:42:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"길드원 중 일부는 그녀가 이 모습임을 알고 있을테고··· 몇 명은 아니겠지요.","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0039260","time":"2026-03-04T16:42:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"!힘","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0039261","time":"2026-03-04T16:42:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'마리우스'의 힘 판정 :\n[5] + [1] = [6]\n결과 : 쓰라린 실패, 운명을 빗겨갈 순 없습니다.","characters":[]},{"id":"RP-III-0039262","time":"2026-03-04T16:43:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"오늘도 검을 수없이 집어 볏짚을 향해 내려꽂지만.","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0039263","time":"2026-03-04T16:43:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"지금의 몸 상태로는···. 가능할 리가 없습니다.","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0039264","time":"2026-03-04T16:43:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"게다가 마리우스는······.","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0039265","time":"2026-03-04T16:43:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"그녀의 뒤에서 뒷받침해주던 가려진 태양의 존재마저 잃었으니까요.","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0039266","time":"2026-03-04T16:43:00+09:00","room":"RP III","name":"션","profile":"션","identity":"reviewed","type":"dialogue","body":"\"으앗!\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0039267","time":"2026-03-04T16:44:00+09:00","room":"RP III","name":"션","profile":"션","identity":"reviewed","type":"dialogue","body":"!민첩","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0039268","time":"2026-03-04T16:44:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 대체, 어디가! 얼마나! 더 부족한 건데! ”","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0039269","time":"2026-03-04T16:44:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'션'의 민첩 판정 :\n[6] + [4] = [10]\n결과 : 훌륭한 성공, 운명이 당신을 이끕니다.","characters":[]},{"id":"RP-III-0039270","time":"2026-03-04T16:44:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"쾅, 칼을 다시금 내려 꽂습니다···.","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0039271","time":"2026-03-04T16:44:00+09:00","room":"RP III","name":"션","profile":"션","identity":"reviewed","type":"dialogue","body":"지붕에서 골아떨어졌던 션이 떨어졌지만, 고양이처럼 휘리릭 몸을 틀어 착지했다.","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0039272","time":"2026-03-04T16:44:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"!힘","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0039273","time":"2026-03-04T16:44:00+09:00","room":"RP III","name":"션","profile":"션","identity":"reviewed","type":"dialogue","body":"\"휴, 머리 깨질 뻔했네….\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0039274","time":"2026-03-04T16:44:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'마리우스'의 힘 판정 :\n[11] + [1] = [12]\n결과 : 완벽한 성공, 운명은 당신의 편입니다.","characters":[]},{"id":"RP-III-0039275","time":"2026-03-04T16:44:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"쾅! 실패 이후에 분노 가득찬 공격은···.","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0039276","time":"2026-03-04T16:44:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"빠르게 볏짚을 향해 돌진했고.","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0039277","time":"2026-03-04T16:44:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"볏짚은 이제는 모양도 제대로 남기지 않은 채 사라졌습니다.","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0039278","time":"2026-03-04T16:45:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"왜 온 몸을 채우는, 털을 곤두세우게 하는 분노가 있어야만 성공하는 거죠? 조용히 웅얼입니다.","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0039279","time":"2026-03-04T16:45:00+09:00","room":"RP III","name":"션","profile":"션","identity":"reviewed","type":"dialogue","body":"션이 한숨 돌리면서 무한의 담배 케이스 속에서 마력초 궐련을 꺼내 물었다. 그러다가 볏짚을 부모의 원수라도 되는 양 세차게 때려대는 마리우스를 발견했다.\n\n\"마리우스 경, 얼레리요? 원래 투구를 벗고 다녔었나?\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0039280","time":"2026-03-04T16:46:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"빤히 션을 바라보았습니다. 잘 알아차리는군요···.\n\n“ 아니요, 최근에 들어서야 벗었습니다. ”","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0039281","time":"2026-03-04T16:46:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"마리우스는 검을 고쳐잡고, 다시금 볏짚을 향해 내려칩니다.","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0039282","time":"2026-03-04T16:46:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"!힘","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0039283","time":"2026-03-04T16:46:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'마리우스'의 힘 판정 :\n[8] + [1] = [9]\n결과 : 훌륭한 성공, 운명이 당신을 이끕니다.","characters":[]},{"id":"RP-III-0039284","time":"2026-03-04T16:46:00+09:00","room":"RP III","name":"션","profile":"션","identity":"reviewed","type":"dialogue","body":"\"오호라, 벗고 다니니 어떤가. 햇빛이 너무 밝진 않고?\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0039285","time":"2026-03-04T16:47:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"슥, 가벼운 소리를 내며 검이 볏짚을 위에서부터 아래로 가로지르고···.","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0039286","time":"2026-03-04T16:47:00+09:00","room":"RP III","name":"션","profile":"션","identity":"reviewed","type":"dialogue","body":"션은 뒷자리에 걸터앉아서 마리우스를 구경하기 시작했다.","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0039287","time":"2026-03-04T16:47:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 햇빛이 밝지는 않습니다···. 하도 오래 밖에 있어서 이제는 모르겠습니다. ”","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0039288","time":"2026-03-04T16:47:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"얼굴을 찌푸리고 검에만 몰두하는 것이 꽤 좋은 모습일지도 모르겠습니다. 하지만 필히 마리우스의 속은 곯아있는 것이 분명합니다. 분노로 얼룩진 검에서는 강한 힘만이 빠져나오고. 겨우 침착을 얻어낸 후 마리우스가 검을 내려치자···.","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0039289","time":"2026-03-04T16:47:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"!힘","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0039290","time":"2026-03-04T16:48:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'마리우스'의 힘 판정 :\n[7] + [1] = [8]\n결과 : 훌륭한 성공, 운명이 당신을 이끕니다.","characters":[]},{"id":"RP-III-0039291","time":"2026-03-04T16:48:00+09:00","room":"RP III","name":"션","profile":"션","identity":"reviewed","type":"dialogue","body":"\"그러고보니까 검도 쓰기 시작했군. 무슨 심경의 변화라도 있었는감?\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0039292","time":"2026-03-04T16:48:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"검은 부드럽게 볏짚을 훑어갑니다.\n\n” ······ 굳이 개입하셔야 하는 정도의 심경 변화는 아닙니다. 단순히 들어야겠다는 생각이 들어서요. “","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0039293","time":"2026-03-04T16:50:00+09:00","room":"RP III","name":"션","profile":"션","identity":"reviewed","type":"dialogue","body":"\"개입할 생각은 없네만 큰 변화 같기도 한걸.\"\n\n담배 끄트머리에 불을 붙이기 위해, 션은 부싯돌과 철편이 아닌 새로운 도구를 꺼냈다. 그것은 바로 새로이 개발된 간이 화섭통이었다. 멜라니온이 손에 철가루 묻히지 말라며 전해준 물건이다.","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0039294","time":"2026-03-04T16:51:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"큰 변화. 조용히 그 단어를 곱씹었습니다. 변화라기보다는···. 원래 존재하던 기름에 작은 불이 붙었을 뿐일 것 같다는 생각에, 마리우스는 조용히 고개를 내젖습니다.\n\n“ 그렇게 큰 건 아닌 것 같습니다, 아직까지는요. ”","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0039295","time":"2026-03-04T16:52:00+09:00","room":"RP III","name":"션","profile":"션","identity":"reviewed","type":"dialogue","body":"그는 은색 쇠뭉치 하나를 꺼내 뚜껑을 열고 부싯돌을 꼼지락대 불을 피우고 연기를 뱉어낸다.\n\n\"작은 불씨라도 들불과 닿으면 크게 번지기 마련.\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0039296","time":"2026-03-04T16:52:00+09:00","room":"RP III","name":"션","profile":"션","identity":"reviewed","type":"dialogue","body":"화통을 품 속에 집어넣고는 다리를 꼬았다.\n\n\"억지로 칼을 휘두르지 말게나. 꺾이기 쉬우니까.\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0039297","time":"2026-03-04T16:54:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"억지로? 반 강제로 칼을 휘두른 건가? 마리우스는 흑빛의 검을 붙잡은 제 손을 바라봅니다. 어디서도 보지 못했던 오묘한 눈이 손을 이리저리 관찰합니다.\n\n“ 억지로? 제가 선택해서 검을 든 건데···. 억지로 검을 든 것처럼 보이십니까? ”\n\n따지는 것이 아닌, 순수한 물음이었다. 자신이 검을 드는데에 더 나은 방법이 있다면, 받아들일 각오로.","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0039298","time":"2026-03-04T16:57:00+09:00","room":"RP III","name":"션","profile":"션","identity":"reviewed","type":"dialogue","body":"\"화를 내면서 칼을 놀리는데 어찌 억지가 아니라고 할 수 있겠어? 검사는 항상 유연해야한다네. 민첩하고 상대의 약점을 보고 공략해야하지. 무식하게 힘으로 밀어붙이는 건 오거들이나 하는 짓이고.\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0039299","time":"2026-03-04T16:58:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ ······ 그치만 처음부터 검을 잡은 이유가 분노였다면요? 그것을 제외하고는 검을 들 이유가 없다면, 어쩔 수 없이 분노를 도구로서 이용해야 하지 않겠습니까? ”\n\n머뭇거리며, 검을 내동댕이쳤다. 다시금 조각나며 기화하듯 사라지는 검.","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0039300","time":"2026-03-04T17:01:00+09:00","room":"RP III","name":"션","profile":"션","identity":"reviewed","type":"dialogue","body":"\"하하하, 전쟁 시절에 증오와 경멸이 동기부여가 되었던 친구들이 얼마나 되었을 것 같나? 그들은 지금 다 어디 있을까? 격노가 본심은 물론 목숨도 빼앗아가버렸다네.\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0039301","time":"2026-03-04T17:02:00+09:00","room":"RP III","name":"션","profile":"션","identity":"reviewed","type":"dialogue","body":"\"화를 내기는 쉽지만 적절한 방법으로 화를 내기는 쉽지 않아.\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0039302","time":"2026-03-04T17:02:00+09:00","room":"RP III","name":"션","profile":"션","identity":"reviewed","type":"dialogue","body":"션은 무슨 말인지 알겠냐는 듯 담배를 입에 물었다.","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0039303","time":"2026-03-04T17:03:00+09:00","room":"RP III","name":"션","profile":"션","identity":"reviewed","type":"dialogue","body":"\"세상에, 나 방금 멜라토닌 씨 같았지?\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0039304","time":"2026-03-04T17:03:00+09:00","room":"RP III","name":"션","profile":"션","identity":"reviewed","type":"dialogue","body":"\"진짜 나이를 먹었나….\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0039305","time":"2026-03-04T17:04:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"한숨 푹 내쉬고. 연병장에 털썩 주저앉았습니다. 두 손으로는 마른세수하듯 얼굴을 부여잡고서는···.","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0039306","time":"2026-03-04T17:04:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 모르겠습니다, 션 씨. 하나도 이해가 가는 게 없어요. ”","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0039307","time":"2026-03-04T17:04:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 검을 잡아야 뭐라도 될 것 같은데, 잡는 이유마저도···. 분노 때문이면. ”","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0039308","time":"2026-03-04T17:04:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 제가 어떻게, 검을 잘 잡고 이끌어가야 한다는 겁니까···? ”","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0039309","time":"2026-03-04T17:12:00+09:00","room":"RP III","name":"션","profile":"션","identity":"reviewed","type":"dialogue","body":"션이 자리에서 일어섰다. 그러고는 나무로 만든 아밍소드를 들어서 마리우스의 정수리를 콩 때렸다.\n\n\"바보 같긴. 그걸 반드시 자네가 이끌어 가야 하나? 그림자를 짊어지고 빛을 향해 나아가는 것은 자네 뿐이 아닐세. 동료들의 도움을 받아도 괜찮고, 여러 방법을 찾아보아도 괜찮지. 그러려고 들어온 길드가 아닌가.\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0039310","time":"2026-03-04T17:12:00+09:00","room":"RP III","name":"션","profile":"션","identity":"reviewed","type":"dialogue","body":"그러고는 킥킥거리면서 한마디를 덧붙였다.\n\n\"방금 내 일격도 못 막으면서 칼로 이끌기는 무슨.\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0039311","time":"2026-03-04T17:17:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"아얏, 가만히 션에게 머리를 맞고서는. 곰곰히 생각하기 시작했습니다. 도움을 받는다···. 길드원에게 도움을 받는다? 하지만 당장이라고 스승이 되어달라고 하고 싶은 사람도 없고, 해줄 사람도 없을 것 같습니다.","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0039312","time":"2026-03-04T17:17:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"빛을 향해 나아가는 것이 아니라면, 달라질까요.","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0039313","time":"2026-03-04T17:18:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"그림자를 머금고 어둠으로 그것과 함께 추락하고자 하는 것이 목표라면···. 그 누구도 다가오지 않을 것 같다는 공포감에 사로잡힙니다.","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0039314","time":"2026-03-04T17:22:00+09:00","room":"RP III","name":"션","profile":"션","identity":"reviewed","type":"dialogue","body":"\"또, 또, 헛생각.\"\n\n목검 날이 탁, 마리우스의 이마를 두드렸다.\n\n\"성급해하지 말고 더 많은 사람들과 친해져 보라고. 누구에게나 배울 점은 있으니까. 그리고… 그렇지, 같이 의뢰라도 가는 게 좋아보여.\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0039315","time":"2026-03-04T17:23:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 윽, ”\n\n가만히 목검 받아내고 얼굴 찡그립니다. 의뢰? 지금 이렇게 아무것도 못하는데 의뢰를 나갈 수 있을까요.\n\n“ 당, 당장 제가 이런데요, 의뢰 나가면 짐덩이일겁니다. ”","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0039316","time":"2026-03-04T17:24:00+09:00","room":"RP III","name":"션","profile":"션","identity":"reviewed","type":"dialogue","body":"\"짐덩이라니, 우리 길드 이름이 뭔지 벌써 잊었나?\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0039317","time":"2026-03-04T17:25:00+09:00","room":"RP III","name":"션","profile":"션","identity":"reviewed","type":"dialogue","body":"션이 마리우스에게 헤드락을 걸었다. 그 모습은 기술보다는 마치 옆구리에 그녀를 끼우는 것처럼 보였으리라.\n\n\"으이구, 원래 처음은 어설프게 시작하는 게야. 마리우스 경은 스스로에 대한 기대감 너무 높구먼!\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0039318","time":"2026-03-04T17:26:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 으앗, 으, ”\n\n어설프다···. 항상 최고를 기대받았던 그녀로서는 스스로에게 용납되지 않았지만. 션이 그런다면야···.\n\n“ 네, 그러면···. 뭐든 골라서 나가보겠습니다. ”","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0039319","time":"2026-03-04T17:27:00+09:00","room":"RP III","name":"션","profile":"션","identity":"reviewed","type":"dialogue","body":"\"으하하, 돼지 고양이 녀석이랑 부대껴서 쇳가루 마시고 살던 꼬맹이에게 뭘 그리 기대할 줄 알고?\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0039320","time":"2026-03-04T17:27:00+09:00","room":"RP III","name":"션","profile":"션","identity":"reviewed","type":"dialogue","body":"그리고 이 틈을 타 헬리오스를 마구마구 흉보았다!","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0039321","time":"2026-03-04T17:28:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"원래 그렇게 안 살았다고! 작은 불만감이 나오지만···. 음, 뭐 어때요. 가만히 옆구리에서 괴롭힘만 당합니다.","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0039322","time":"2026-03-04T17:29:00+09:00","room":"RP III","name":"션","profile":"션","identity":"reviewed","type":"dialogue","body":"\"돼지 고양이 자식이 얼마나 자네를 오냐오냐 키웠으면 이만큼 잘난 척을 해대는감? 나는 14살 때 선배들에게 마구 두들겨 맞고 살았는걸!\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0039323","time":"2026-03-04T17:42:00+09:00","room":"RP III","name":"션","profile":"션","identity":"reviewed","type":"dialogue","body":"\"자자, 특별히 14살이 된 자네에게 내 14살을 체험시켜주지. 어디서 못 받는 검술 강습이라고?\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0039324","time":"2026-03-04T17:42:00+09:00","room":"RP III","name":"션","profile":"션","identity":"reviewed","type":"dialogue","body":"마리우스의 나이도 제대로 알지 못한 션은 그녀를 놔주더니 목검을 고쳐쥐었다. 그러고는 그녀가 본 적 없던 식으로 마구 따끔한 일격들을 날려대었다. 카프리제가 저녁 먹으라고 부를 때까지!","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0039325","time":"2026-03-04T17:42:00+09:00","room":"RP III","name":"션","profile":"션","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0039326","time":"2026-03-04T17:42:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"다음을 기대할게..!","characters":[]}]};
